"""Complete ordered foundation route used by the professional studios.

The route is intentionally finite: it teaches the language and the vocabulary
needed to read and build a layered desktop application.  Reference material
stays in the encyclopedia; assessment uses generated tasks, not memorised MCQs.
"""
from __future__ import annotations
from dataclasses import dataclass


@dataclass(frozen=True)
class Lesson:
    slug: str
    title: str
    level: int
    theory: str
    code: str
    walkthrough: str
    challenge: str
    hint: str
    tokens: tuple[str, ...]
    mode: str = "syntax"


def _lesson(slug, title, level, theory, code, challenge, tokens=(), mode="syntax"):
    return Lesson(slug, title, level, theory, code,
        "Прочитай пример сверху вниз. Назови тип каждого значения, результат выражения и причину каждого отступа. "
        "Затем измени пример и проверь предположение запуском.",
        challenge, "Раздели задачу на входные данные, преобразование и наблюдаемый результат.", tuple(tokens), mode)


